319	/**
320	 * What the application's own declared postbuild purge would remove from a built
321	 * lane, measured without shipping it.
322	 *
323	 * The purge is run with the repository's own `purgecss.config.js` — so its
324	 * hand-written extractor is the one that decides which class names survive — and
325	 * only the content and stylesheet globs are retargeted at the lane being
326	 * measured, because those globs are written against create-react-app's output
327	 * layout (`build/index.html`, `build/static/js/*.js`, `build/static/css/*.css`)
328	 * and no other layout can match them. The result is written to a scratch
329	 * directory and discarded; neither lane's recorded output contains it.
330	 */
331	export async function measureDeclaredCssPurge(
332		lane: string,
333		directory: string,
334		inventory: LaneInventory,
335		scratch: string,
336		root = targetRoot,
337	): Promise<CssPurgeMeasurement> {
338		const stylesheets = filesWithExtension(inventory, cssExtension);
339		const content = [
340			...filesWithExtension(inventory, htmlExtension),
341			...filesWithExtension(inventory, javaScriptExtension),
342		];
343		await rm(scratch, { recursive: true, force: true });
344		await mkdir(scratch, { recursive: true });
345		await run(
346			path.join(root, 'node_modules/.bin/purgecss'),
347			[
348				// The declared config path, resolved by purgecss against its own working
349				// directory exactly as the application's postbuild hook passes it.
350				'--config',
351				'./purgecss.config.js',
352				'--css',
353				...stylesheets.map((file) => path.join(directory, file)),
354				'--content',
355				...content.map((file) => path.join(directory, file)),
356				'--output',
357				scratch,
358			],
359			root,
360		);
361		const before = await totalBytes(directory, stylesheets);
362		const purged = await readdir(scratch);
363		const after = await totalBytes(scratch, purged);
364		await rm(scratch, { recursive: true, force: true });
365		return {
366			lane,
367			stylesheets,
368			bytesBeforePurge: before,
369			bytesAfterPurge: after,
370			reductionPercent: roundToTwoDecimals(((before - after) / before) * 100),
371			shipped: false,
372		};
373	}
