375	export type BuildLevelParity = Readonly<{
376		baselineOnlyPaths: readonly string[];
377		targetOnlyPaths: readonly string[];
378		sharedPaths: readonly string[];
379		byteIdenticalSharedPaths: readonly string[];
380	}>;
