382	/**
383	 * Build-level parity: which emitted paths each lane has, which they share, and
384	 * which shared paths are byte identical. Nothing here observes behaviour, and
385	 * nothing here may be read as behavioural parity.
386	 */
387	export function buildLevelParity(
388		baseline: LaneInventory,
389		target: LaneInventory,
390	): BuildLevelParity {
391		const baselineByPath = new Map(baseline.files.map((file) => [file.path, file.sha256]));
392		const targetByPath = new Map(target.files.map((file) => [file.path, file.sha256]));
393		const shared = [...baselineByPath.keys()]
394			.filter((file) => targetByPath.has(file))
395			.sort(compareUtf16CodeUnits);
396		return {
397			baselineOnlyPaths: [...baselineByPath.keys()]
398				.filter((file) => !targetByPath.has(file))
399				.sort(compareUtf16CodeUnits),
400			targetOnlyPaths: [...targetByPath.keys()]
401				.filter((file) => !baselineByPath.has(file))
402				.sort(compareUtf16CodeUnits),
403			sharedPaths: shared,
404			byteIdenticalSharedPaths: shared.filter(
405				(file) => baselineByPath.get(file) === targetByPath.get(file),
406			),
407		};
408	}
