    return () => {
      document.title = 'LinkFree'
    }
  }, [username])

  return (
    <>
      {!singleUser && (
        <header>
          <Navbar
            start={
              <Link to="/search" aria-label="Go back to Search">
                <GetIcons iconName="arrowLeft" size={20} />
              </Link>
            }
          />
        </header>
      )}
      <main>
        {showProgress && <ProgressBar mode="indeterminate" />}
        {skeleton && <Placeholder />}
        {error && <ErrorPage />}
        {!error && !skeleton && (
