const BASELINE_REACT_CACHE_BUST_QUERY = '?__uncache=versionless-deterministic';
const BASELINE_REACT_MAIN_ASSETS = [
	{ pathname: '/favicon.ico', resolvedFile: 'favicon.ico', mime: 'image/x-icon' },

